package glitch

import data.glitch_lib

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    comm_keywords := {"protocol", "transport", "encryption", "ssl", "tls", "secure", "endpoint", "api", "gateway", "service", "microservice"}
    comm_pattern := sprintf("(?i)(%s)", [concat("|", comm_keywords)])
    regex.match(comm_pattern, attr.name)

    value := attr.value
    value.ir_type == "String"
    insecure_protocols := {"http", "ftp", "smtp", "plaintext"}
    insecure_pattern := sprintf("(?i)(%s)", [concat("|", insecure_protocols)])
    regex.match(insecure_pattern, value.value)

    integrity_keywords := {"checksum", "validation", "verify", "integrity", "hash", "mac"}
    integrity_pattern := sprintf("(?i)(%s)", [concat("|", integrity_keywords)])
    integrity_attrs := {a | a := attrs[_]; regex.match(integrity_pattern, a.name)}
    count(integrity_attrs) == 0

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing integrity check in network communication - Communication protocol configured without integrity verification. (CWE-353)"
    }
}

